WITH kept AS (SELECT s.* FROM products s WHERE EXISTS (SELECT 1 FROM store_sales x WHERE x.product_id = s.id AND x.revenue >= 3300)) SELECT CASE WHEN cost >= 630 THEN 'LARGE' ELSE 'SMALL' END AS cost_tier, category, supplier_id, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) FILTER (WHERE category = 'Grocery') AS grocery_rows, COUNT(DISTINCT id) AS distinct_ids_2, GROUPING(CASE WHEN cost >= 630 THEN 'LARGE' ELSE 'SMALL' END) AS grouping_id FROM kept GROUP BY ROLLUP (CASE WHEN cost >= 630 THEN 'LARGE' ELSE 'SMALL' END, category, supplier_id) HAVING COUNT(DISTINCT id) < 1
